24	FileSegment::FileSegment(
25	        size_t offset_,
26	        size_t size_,
27	        const Key & key_,
28	        IFileCache * cache_,
29	        State download_state_,
30	        bool is_persistent_)
31	    : segment_range(offset_, offset_ + size_ - 1)
32	    , download_state(download_state_)
33	    , file_key(key_)
34	    , cache(cache_)
35	#ifndef NDEBUG
36	    , log(&Poco::Logger::get(fmt::format("FileSegment({}) : {}", getHexUIntLowercase(key_), range().toString())))
37	#else
38	    , log(&Poco::Logger::get("FileSegment"))
39	#endif
40	    , is_persistent(is_persistent_) /// Not really used for now, see PR 36171
41	{
42	    /// On creation, file segment state can be EMPTY, DOWNLOADED, DOWNLOADING.
43	    switch (download_state)
44	    {
45	        /// EMPTY is used when file segment is not in cache and
46	        /// someone will _potentially_ want to download it (after calling getOrSetDownloader()).
47	        case (State::EMPTY):
48	        {
49	            break;
50	        }
51	        /// DOWNLOADED is used either on initial cache metadata load into memory on server startup
52	        /// or on reduceSizeToDownloaded() -- when file segment object is updated.
53	        case (State::DOWNLOADED):
54	        {
55	            reserved_size = downloaded_size = size_;
56	            break;
57	        }
58	        /// DOWNLOADING is used only for write-through caching (e.g. getOrSetDownloader() is not
59	        /// needed, downloader is set on file segment creation).
60	        case (State::DOWNLOADING):
61	        {
62	            downloader_id = getCallerId();
63	            break;
64	        }
65	        case (State::SKIP_CACHE):
66	        {
67	            break;
68	        }
69	        default:
70	        {
71	            throw Exception(ErrorCodes::REMOTE_FS_OBJECT_CACHE_ERROR, "Can create cell with either EMPTY, DOWNLOADED, DOWNLOADING state");
72	        }
73	    }
74	}
