209	void FileSegment::write(const char * from, size_t size, size_t offset_)
210	{
211	    if (!size)
212	        throw Exception(ErrorCodes::REMOTE_FS_OBJECT_CACHE_ERROR, "Writing zero size is not allowed");
213	
214	    if (availableSize() < size)
215	        throw Exception(
216	            ErrorCodes::REMOTE_FS_OBJECT_CACHE_ERROR,
217	            "Not enough space is reserved. Available: {}, expected: {}", availableSize(), size);
218	
219	    if (!isDownloader())
220	        throw Exception(ErrorCodes::LOGICAL_ERROR,
221	                        "Only downloader can do the downloading. (CallerId: {}, DownloaderId: {})",
222	                        getCallerId(), downloader_id);
223	
224	    if (downloaded_size == range().size())
225	        throw Exception(ErrorCodes::REMOTE_FS_OBJECT_CACHE_ERROR,
226	                        "Attempt to write {} bytes to offset: {}, but current file segment is already fully downloaded",
227	                        size, offset_);
228	
229	    auto download_offset = range().left + downloaded_size;
230	    if (offset_ != download_offset)
231	        throw Exception(ErrorCodes::REMOTE_FS_OBJECT_CACHE_ERROR,
232	                        "Attempt to write {} bytes to offset: {}, but current download offset is {}",
233	                        size, offset_, download_offset);
234	
235	    {
236	        std::lock_guard segment_lock(mutex);
237	        assertNotDetached(segment_lock);
238	    }
239	
240	    if (!cache_writer)
241	    {
242	        if (downloaded_size > 0)
243	            throw Exception(ErrorCodes::LOGICAL_ERROR,
244	                            "Cache writer was finalized (downloaded size: {}, state: {})",
245	                            downloaded_size, stateToString(download_state));
246	
247	        auto download_path = getPathInLocalCache();
248	        cache_writer = std::make_unique<WriteBufferFromFile>(download_path);
249	    }
250	
251	    try
252	    {
253	        cache_writer->write(from, size);
254	
255	        std::lock_guard download_lock(download_mutex);
256	
257	        cache_writer->next();
258	
259	        downloaded_size += size;
260	    }
261	    catch (Exception & e)
262	    {
263	        std::lock_guard segment_lock(mutex);
264	
265	        wrapWithCacheInfo(e, "while writing into cache", segment_lock);
266	
267	        setDownloadFailed(segment_lock);
268	
269	        cv.notify_all();
270	
271	        throw;
272	    }
273	
274	    assert(getDownloadOffset() == offset_ + size);
275	}
