317	size_t FileSegment::finalizeWrite()
318	{
319	    std::lock_guard segment_lock(mutex);
320	
321	    if (!cache_writer)
322	        throw Exception(ErrorCodes::LOGICAL_ERROR, "Cache writer not initialized");
323	
324	    size_t size = cache_writer->offset();
325	
326	    if (size == 0)
327	        throw Exception(ErrorCodes::REMOTE_FS_OBJECT_CACHE_ERROR, "Writing zero size is not allowed");
328	
329	    assertNotDetached(segment_lock);
330	
331	    try
332	    {
333	        cache_writer->next();
334	    }
335	    catch (Exception & e)
336	    {
337	        wrapWithCacheInfo(e, "while writing into cache", segment_lock);
338	
339	        setDownloadFailed(segment_lock);
340	
341	        cv.notify_all();
342	
343	        throw;
344	    }
345	
346	    downloaded_size += size;
347	
348	    if (downloaded_size != range().size())
349	        throw Exception(ErrorCodes::LOGICAL_ERROR, "Expected downloaded size to equal file segment size ({} == {})", downloaded_size, range().size());
350	
351	    setDownloaded(segment_lock);
352	
353	    return size;
354	}
