356	FileSegment::State FileSegment::wait()
357	{
358	    std::unique_lock segment_lock(mutex);
359	
360	    if (is_detached)
361	        throw Exception(
362	            ErrorCodes::LOGICAL_ERROR,
363	            "Cache file segment is in detached state, operation not allowed");
364	
365	    if (downloader_id.empty())
366	        return download_state;
367	
368	    if (download_state == State::EMPTY)
369	        throw Exception(ErrorCodes::REMOTE_FS_OBJECT_CACHE_ERROR, "Cannot wait on a file segment with empty state");
370	
371	    if (download_state == State::DOWNLOADING)
372	    {
373	        LOG_TEST(log, "{} waiting on: {}, current downloader: {}", getCallerId(), range().toString(), downloader_id);
374	
375	        assert(!downloader_id.empty());
376	        assert(downloader_id != getCallerId());
377	
378	        cv.wait_for(segment_lock, std::chrono::seconds(60));
379	    }
380	
381	    return download_state;
382	}
