384	bool FileSegment::reserve(size_t size)
385	{
386	    if (!size)
387	        throw Exception(ErrorCodes::REMOTE_FS_OBJECT_CACHE_ERROR, "Zero space reservation is not allowed");
388	
389	    {
390	        std::lock_guard segment_lock(mutex);
391	        assertNotDetached(segment_lock);
392	
393	        auto caller_id = getCallerId();
394	        bool is_downloader = caller_id == downloader_id;
395	        if (!is_downloader)
396	        {
397	            throw Exception(
398	                ErrorCodes::LOGICAL_ERROR,
399	                "Space can be reserved only by downloader (current: {}, expected: {})",
400	                caller_id, downloader_id);
401	        }
402	
403	        if (downloaded_size + size > range().size())
404	            throw Exception(ErrorCodes::REMOTE_FS_OBJECT_CACHE_ERROR,
405	                            "Attempt to reserve space too much space ({}) for file segment with range: {} (downloaded size: {})",
406	                            size, range().toString(), downloaded_size);
407	
408	        assert(reserved_size >= downloaded_size);
409	    }
410	
411	    /**
412	     * It is possible to have downloaded_size < reserved_size when reserve is called
413	     * in case previous downloader did not fully download current file_segment
414	     * and the caller is going to continue;
415	     */
416	    size_t free_space = reserved_size - downloaded_size;
417	    size_t size_to_reserve = size - free_space;
418	
419	    std::lock_guard cache_lock(cache->mutex);
420	
421	    bool reserved = cache->tryReserve(key(), offset(), size_to_reserve, cache_lock);
422	
423	    if (reserved)
424	    {
425	        std::lock_guard segment_lock(mutex);
426	        reserved_size += size;
427	    }
428	
429	    return reserved;
430	}
