538	void FileSegment::completeUnlocked(std::lock_guard<std::mutex> & cache_lock, std::lock_guard<std::mutex> & segment_lock)
539	{
540	    bool is_last_holder = cache->isLastFileSegmentHolder(key(), offset(), cache_lock, segment_lock);
541	
542	    if (is_last_holder && download_state == State::SKIP_CACHE)
543	    {
544	        cache->remove(key(), offset(), cache_lock, segment_lock);
545	        return;
546	    }
547	
548	    if (download_state == State::SKIP_CACHE || is_detached)
549	        return;
550	
551	    if (isDownloaderImpl(segment_lock)
552	        && download_state != State::DOWNLOADED
553	        && getDownloadedSize(segment_lock) == range().size())
554	    {
555	        setDownloaded(segment_lock);
556	    }
557	
558	    assertNotDetached(segment_lock);
559	
560	    if (download_state == State::DOWNLOADING || download_state == State::EMPTY)
561	    {
562	        /// Segment state can be changed from DOWNLOADING or EMPTY only if the caller is the
563	        /// downloader or the only owner of the segment.
564	
565	        bool can_update_segment_state = isDownloaderImpl(segment_lock) || is_last_holder;
566	
567	        if (can_update_segment_state)
568	            download_state = State::PARTIALLY_DOWNLOADED;
569	    }
570	
571	    try
572	    {
573	        completeImpl(cache_lock, segment_lock);
574	    }
575	    catch (...)
576	    {
577	        if (!downloader_id.empty() && isDownloaderImpl(segment_lock))
578	            downloader_id.clear();
579	
580	        cv.notify_all();
581	        throw;
582	    }
583	
584	    cv.notify_all();
585	}
586	
587	void FileSegment::completeImpl(std::lock_guard<std::mutex> & cache_lock, std::lock_guard<std::mutex> & segment_lock)
588	{
589	    bool is_last_holder = cache->isLastFileSegmentHolder(key(), offset(), cache_lock, segment_lock);
590	
591	    if (is_last_holder
592	        && (download_state == State::PARTIALLY_DOWNLOADED || download_state == State::PARTIALLY_DOWNLOADED_NO_CONTINUATION))
593	    {
594	        size_t current_downloaded_size = getDownloadedSize(segment_lock);
595	        if (current_downloaded_size == 0)
596	        {
597	            download_state = State::SKIP_CACHE;
598	            LOG_TEST(log, "Remove cell {} (nothing downloaded)", range().toString());
599	            cache->remove(key(), offset(), cache_lock, segment_lock);
600	        }
601	        else
602	        {
603	            /**
604	            * Only last holder of current file segment can resize the cell,
605	            * because there is an invariant that file segments returned to users
606	            * in FileSegmentsHolder represent a contiguous range, so we can resize
607	            * it only when nobody needs it.
608	            */
609	            download_state = State::PARTIALLY_DOWNLOADED_NO_CONTINUATION;
610	            LOG_TEST(log, "Resize cell {} to downloaded: {}", range().toString(), current_downloaded_size);
611	            cache->reduceSizeToDownloaded(key(), offset(), cache_lock, segment_lock);
612	        }
613	
614	        markAsDetached(segment_lock);
615	
616	        if (cache_writer)
617	        {
618	            cache_writer->finalize();
619	            cache_writer.reset();
620	            remote_file_reader.reset();
621	        }
622	    }
623	
624	    if (!downloader_id.empty() && (isDownloaderImpl(segment_lock) || is_last_holder))
625	    {
626	        LOG_TEST(log, "Clearing downloader id: {}, current state: {}", downloader_id, stateToString(download_state));
627	        downloader_id.clear();
628	    }
629	
630	    LOG_TEST(log, "Completed file segment: {}", getInfoForLogImpl(segment_lock));
631	    assertCorrectnessImpl(segment_lock);
632	}
