784	FileSegmentsHolder::~FileSegmentsHolder()
785	{
786	    /// In CacheableReadBufferFromRemoteFS file segment's downloader removes file segments from
787	    /// FileSegmentsHolder right after calling file_segment->complete(), so on destruction here
788	    /// remain only uncompleted file segments.
789	
790	    IFileCache * cache = nullptr;
791	
792	    for (auto file_segment_it = file_segments.begin(); file_segment_it != file_segments.end();)
793	    {
794	        auto current_file_segment_it = file_segment_it;
795	        auto & file_segment = *current_file_segment_it;
796	
797	        if (!cache)
798	            cache = file_segment->cache;
799	
800	        try
801	        {
802	            bool is_detached = false;
803	
804	            {
805	                std::lock_guard segment_lock(file_segment->mutex);
806	                is_detached = file_segment->isDetached(segment_lock);
807	                if (is_detached)
808	                    file_segment->assertDetachedStatus(segment_lock);
809	            }
810	
811	            if (is_detached)
812	            {
813	                /// This file segment is not owned by cache, so it will be destructed
814	                /// at this point, therefore no completion required.
815	                file_segment_it = file_segments.erase(current_file_segment_it);
816	                continue;
817	            }
818	
819	            /// File segment pointer must be reset right after calling complete() and
820	            /// under the same mutex, because complete() checks for segment pointers.
821	            std::lock_guard cache_lock(cache->mutex);
822	
823	            file_segment->complete(cache_lock);
824	
825	            file_segment_it = file_segments.erase(current_file_segment_it);
826	        }
827	        catch (...)
828	        {
829	            tryLogCurrentException(__PRETTY_FUNCTION__);
830	        }
831	    }
832	}
